INSERT INTO feature VALUES('atom-sorts','descriptions','Atom sorts','levitated-descriptions','partial','notable',NULL,'A theory block declares an atom sort, `sort Name : Atom;`, whose elements have equality and swapping as their only structure; the Theory value keeps it under its own tag, a binder over it is refused by name, and an operation''s port abstracts its atoms with `bind (a : Name) .` beside `pi+`, a model of such an operation refused by name. A rule term abstracts an atom at such a port, `bind a . t`, and only there: at a `pi+` port the same spelling is the port''s binding field (`second-order-rules`). Matching, the critical pairs and the kernel read an abstraction up to the atom it names. Inside its abstraction a rule term names the atom, an occurrence counted by the abstractions between it and its binder, and an inspected call reads one alike. Where a port takes an atom, a rule stating a freshness condition or moving a variable across an abstraction fires only where its instance names no atom it may not, counting a moved instance''s atoms to their abstractions'' new places, and its overlaps are decided under the condition they compose (`rule-conditions`); a variable split across an abstraction on a left side is refused as undecided.','theory-levitation surface-lowering theory-computads kernel-term','corpus/model/desc/atom-sorts.gandr corpus/pathological/desc/atom-sorts.gandr corpus/model/desc/bind-port.gandr corpus/pathological/desc/bind-port.gandr corpus/model/desc/bind-term.gandr corpus/pathological/desc/bind-term.gandr corpus/model/desc/atom-occurrence.gandr corpus/pathological/desc/atom-occurrence.gandr','corpus/ledger/features/atom-sorts.gandr','#1430 #1561 #1934');
